def solve(mat):
    # Empty matrix determinant is defined as 1
    if not mat:
        return 1
    n = len(mat)
    # Ensure square
    for row in mat:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a copy as mutable list of lists
    a = [list(row) for row in mat]
    # Bareiss algorithm for exact integer determinant
    det = 1
    for k in range(n-1):
        # Find pivot if zero
        if a[k][k] == 0:
            # search for non-zero below
            swap = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            # swap rows k and swap
            a[k], a[swap] = a[swap], a[k]
            det = -det  # row swap changes sign
        pivot = a[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // (a[k-1][k-1] if k>0 else 1)
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j])
                if k > 0:
                    a[i][j] //= a[k-1][k-1]
        # zero out column below pivot
        for i in range(k+1, n):
            a[i][k] = 0
    # The determinant is the last pivot times the sign
    det *= a[n-1][n-1]
    return det

