def solve(mat):
    """Return determinant of a square integer matrix.
    Uses exact arithmetic with Fraction to avoid rounding errors.
    Empty matrix has determinant 1.
    """
    from fractions import Fraction
    if not mat:
        return 1
    n = len(mat)
    for row in mat:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Create a mutable copy of Fractions
    a = [[Fraction(x) for x in row] for row in mat]
    sign = 1
    for k in range(n):
        # Find pivot
        pivot_row = None
        for i in range(k, n):
            if a[i][k] != 0:
                pivot_row = i
                break
        if pivot_row is None:
            return 0
        if pivot_row != k:
            a[k], a[pivot_row] = a[pivot_row], a[k]
            sign = -sign
        pivot = a[k][k]
        # Eliminate rows below
        for i in range(k+1, n):
            factor = a[i][k] / pivot
            if factor == 0:
                continue
            for j in range(k, n):
                a[i][j] -= factor * a[k][j]
    # Determinant is sign * product of diagonal entries
    det = Fraction(sign)
    for i in range(n):
        det *= a[i][i]
    # det should be integer
    return det.numerator // det.denominator if det.denominator != 0 else 0

