    """Count islands in a possibly ragged 2D grid of 0/1.
    Cells are connected orthogonally (up, down, left, right).
    Supports empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited set of (r,c)
    visited = set()
    def neighbors(r, c):
        # up
        if r > 0 and c < len(grid[r-1]):
            yield (r-1, c)
        # down
        if r + 1 < rows and c < len(grid[r+1]):
            yield (r+1, c)
        # left
        if c > 0:
            yield (r, c-1)
        # right
        if c + 1 < len(grid[r]):
            yield (r, c+1)
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] != 1:
                continue
            if (r, c) in visited:
                continue
            # start new island
            count += 1
            stack = [(r, c)]
            while stack:
                i, j = stack.pop()
                if (i, j) in visited:
                    continue
                visited.add((i, j))
                for ni, nj in neighbors(i, j):
                    if (ni, nj) not in visited and grid[ni][nj] == 1:
                        stack.append((ni, nj))
    return count
