    """Return minimum number of coins to make amount using unlimited coins.
    If impossible, return -1.
    classic DP O(amount * len(coins)).
    """
    if amount < 0:
        return -1
    # DP array where dp[i] = min coins for i
    INF = amount + 1  # larger than any possible count
    dp = [0] + [INF] * amount
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
