    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, stay at root (ignore)
        else:
            stack.append(part)
    # Construct simplified path
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

