def solve(n, b):
    """Convert integer n to a string in base b (2 <= b <= 36).
    Digits are 0-9 then a-z. Negative numbers get a leading '-'.
    """
    if not (2 <= b <= 36):
        raise ValueError('Base out of range')
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
        n, r = divmod(n, b)
        res.append(digits[r])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

