    # DP for unlimited coin change, minimize number of coins.
    # Edge cases
    if amount < 0:
        return -1
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
